/**
 * nepui — design tokens
*/

:root {
  color-scheme: light;

  --np-radius: 0.625rem;
  --np-radius-sm: calc(var(--np-radius) * 0.6);
  --np-radius-md: calc(var(--np-radius) * 0.8);
  --np-radius-lg: var(--np-radius);
  --np-radius-xl: calc(var(--np-radius) * 1.4);
  --np-radius-2xl: calc(var(--np-radius) * 1.8);
  --np-radius-3xl: calc(var(--np-radius) * 2.2);
  --np-radius-4xl: calc(var(--np-radius) * 2.6);
  --np-radius-full: 9999px;

  --np-background: #ffffff;
  --np-foreground: #0a0a0a;

  --np-card: #ffffff;
  --np-card-foreground: #0a0a0a;

  --np-popover: #ffffff;
  --np-popover-foreground: #0a0a0a;

  --np-primary: #121212;
  --np-primary-foreground: #ffffff;

  --np-secondary: #f4f4f5;
  --np-secondary-foreground: #18181b;

  --np-muted: #f4f4f5;
  --np-muted-foreground: #71717a;

  --np-accent: #f4f4f5;
  --np-accent-foreground: #18181b;

  --np-destructive: #e7000b;

  --np-success: #16a34a;
  --np-success-foreground: #fafafa;

  --np-warning: #d97706;
  --np-warning-foreground: #fafafa;

  --np-border: #e4e4e7;
  --np-input: #e4e4e7;
  --np-ring: #a1a1a1;

  --np-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --np-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --np-shadow-md:
    0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --np-shadow-lg:
    0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
}

/* Explicit dark theme — class or data-attribute toggle (next-themes, etc.) */
.dark,
[data-theme="dark"] {
  color-scheme: dark;

  --np-radius: 0.625rem;
  --np-radius-sm: calc(var(--np-radius) * 0.6);
  --np-radius-md: calc(var(--np-radius) * 0.8);
  --np-radius-lg: var(--np-radius);
  --np-radius-xl: calc(var(--np-radius) * 1.4);
  --np-radius-2xl: calc(var(--np-radius) * 1.8);
  --np-radius-3xl: calc(var(--np-radius) * 2.2);
  --np-radius-4xl: calc(var(--np-radius) * 2.6);
  --np-radius-full: 9999px;

  --np-background: #0a0a0a;
  --np-foreground: #fafafa;

  --np-card: #0a0a0a;
  --np-card-foreground: #fafafa;

  --np-popover: #ffffff;
  --np-popover-foreground: #0a0a0a;

  --np-primary: #121212;
  --np-primary-foreground: #fafafa;

  --np-secondary: #27272a;
  --np-secondary-foreground: #fafafa;

  --np-muted: #27272a;
  --np-muted-foreground: #a1a1aa;

  --np-accent: #27272a;
  --np-accent-foreground: #fafafa;

  --np-destructive: #e7000b;

  --np-success: #01a041;
  --np-success-foreground: #f0fdf4;

  --np-warning: #ad4407;
  --np-warning-foreground: #fffbeb;

  --np-border: #27272a;
  --np-input: #27272a;
  --np-ring: #737373;

  --np-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.3);
  --np-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.4), 0 1px 2px -1px rgb(0 0 0 / 0.4);
  --np-shadow-md:
    0 4px 6px -1px rgb(0 0 0 / 0.4), 0 2px 4px -2px rgb(0 0 0 / 0.4);
  --np-shadow-lg:
    0 10px 15px -3px rgb(0 0 0 / 0.4), 0 4px 6px -4px rgb(0 0 0 / 0.4);
}

/* OS-level dark mode when no explicit theme has been chosen */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]):not(.light) {
    color-scheme: dark;

    --np-radius: 0.625rem;
    --np-radius-sm: calc(var(--np-radius) * 0.6);
    --np-radius-md: calc(var(--np-radius) * 0.8);
    --np-radius-lg: var(--np-radius);
    --np-radius-xl: calc(var(--np-radius) * 1.4);
    --np-radius-2xl: calc(var(--np-radius) * 1.8);
    --np-radius-3xl: calc(var(--np-radius) * 2.2);
    --np-radius-4xl: calc(var(--np-radius) * 2.6);
    --np-radius-full: 9999px;

    --np-background: #0a0a0a;
    --np-foreground: #fafafa;

    --np-card: #0a0a0a;
    --np-card-foreground: #fafafa;

    --np-popover: #0a0a0a;
    --np-popover-foreground: #fafafa;

    --np-primary: #ffffff;
    --np-primary-foreground: #0a0a0a;

    --np-secondary: #27272a;
    --np-secondary-foreground: #fafafa;

    --np-muted: #27272a;
    --np-muted-foreground: #a1a1aa;

    --np-accent: #27272a;
    --np-accent-foreground: #fafafa;

    --np-destructive: #e7000b;

    --np-success: #01a041;
    --np-success-foreground: #f0fdf4;

    --np-warning: #ad4407;
    --np-warning-foreground: #fffbeb;

    --np-border: #27272a;
    --np-input: #27272a;
    --np-ring: #737373;

    --np-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.3);
    --np-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.4), 0 1px 2px -1px rgb(0 0 0 / 0.4);
    --np-shadow-md:
      0 4px 6px -1px rgb(0 0 0 / 0.4), 0 2px 4px -2px rgb(0 0 0 / 0.4);
    --np-shadow-lg:
      0 10px 15px -3px rgb(0 0 0 / 0.4), 0 4px 6px -4px rgb(0 0 0 / 0.4);
  }
}

/* eslint-disable @typescript-eslint/no-unused-vars */
"use client"

import * as React from "react"

import "../../tokens.css"
import "./button.css"

export type ButtonVariant =
  "default" | "outline" | "secondary" | "ghost" | "destructive"

export type ButtonSize =
  "xs" | "sm" | "default" | "lg" | "icon" | "icon-xs" | "icon-sm" | "icon-lg"

export function cn(
  ...classes: Array<string | number | boolean | null | undefined>
): string {
  return classes.filter(Boolean).join(" ")
}

interface ButtonBaseProps {
  children?: React.ReactNode
  variant?: ButtonVariant
  size?: ButtonSize
  loading?: boolean
  invalid?: boolean
}

interface ButtonAsButtonProps
  extends
    ButtonBaseProps,
    Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, keyof ButtonBaseProps> {
  as?: "button"
  href?: never
}

interface ButtonAsLinkProps
  extends
    ButtonBaseProps,
    Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, keyof ButtonBaseProps> {
  as: "link"
  href: string
}

export type ButtonProps = ButtonAsButtonProps | ButtonAsLinkProps

// Real discriminant check on `props.as`, so TS can actually narrow the union.
function isLinkProps(props: ButtonProps): props is ButtonAsLinkProps {
  return props.as === "link"
}

export const Button = React.forwardRef<
  HTMLButtonElement | HTMLAnchorElement,
  ButtonProps
>((props, ref) => {
  const {
    className,
    variant = "default",
    size = "default",
    loading = false,
    invalid = false,
  } = props

  const classes = cn("np-button", className)

  if (isLinkProps(props)) {
    const {
      as: _as,
      href,
      onClick,
      children,
      variant: _variant,
      size: _size,
      loading: _loading,
      invalid: _invalid,
      className: _className,
      ...linkProps
    } = props

    const handleClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
      if (loading) {
        event.preventDefault()
        return
      }
      onClick?.(event)
    }

    return (
      <a
        ref={ref as React.Ref<HTMLAnchorElement>}
        href={href}
        className={cn(classes, "np-button-link")}
        aria-invalid={invalid || undefined}
        aria-busy={loading || undefined}
        aria-disabled={loading || undefined}
        data-variant={variant}
        data-size={size}
        data-state={loading ? "loading" : undefined}
        {...linkProps}
        onClick={handleClick}
      >
        {children}
      </a>
    )
  }

  const {
    as: _as,
    disabled,
    type = "button",
    onClick,
    children,
    variant: _variant,
    size: _size,
    loading: _loading,
    invalid: _invalid,
    className: _className,
    ...buttonProps
  } = props

  const isDisabled = disabled || loading

  return (
    <button
      ref={ref as React.Ref<HTMLButtonElement>}
      type={type}
      className={classes}
      disabled={isDisabled}
      aria-invalid={invalid}
      aria-busy={loading}
      data-variant={variant}
      data-size={size}
      data-state={loading ? "loading" : isDisabled ? "disabled" : undefined}
      {...buttonProps}
      onClick={onClick}
    >
      {children}
    </button>
  )
})

Button.displayName = "Button"

/* nepui — Button */

button:not(:disabled),
[role="button"]:not(:disabled) {
  cursor: pointer;
}

.np-button,
[data-np-button] {
  --np-button-radius: var(--np-radius-md);
  --np-button-font-size: 0.875rem;
  --np-button-font-weight: 500;
  --np-button-gap: 0.375rem;
  --np-button-height: 2rem;
  --np-button-padding-x: 0.625rem;

  --np-button-bg: var(--np-primary);
  --np-button-color: var(--np-primary-foreground);
  --np-button-border: var(--np-primary);
  --np-button-hover-bg: color-mix(
    in oklch,
    var(--np-primary),
    var(--np-foreground) 20%
  );

  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  position: relative;

  gap: var(--np-button-gap);
  height: var(--np-button-height);
  padding: 0 var(--np-button-padding-x);

  border: 1px solid var(--np-button-border);
  border-radius: var(--np-button-radius);

  background: var(--np-button-bg);
  color: var(--np-button-color);

  font: inherit;
  font-size: var(--np-button-font-size);
  font-weight: var(--np-button-font-weight);
  line-height: 1;

  white-space: nowrap;
  text-decoration: none;
  user-select: none;

  transition:
    background-color 150ms ease,
    color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease,
    transform 100ms ease;

  outline: none;
}

:is([data-np-button], .np-button):hover {
  background: var(--np-button-hover-bg);
}

:is([data-np-button], .np-button):active {
  transform: translateY(1px);
}

:is([data-np-button], .np-button):focus-visible {
  border-color: var(--np-ring);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-ring), transparent 50%);
}

:is([data-np-button], .np-button):disabled,
:is([data-np-button], .np-button)[aria-disabled="true"] {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

:is([data-np-button], .np-button)[aria-invalid="true"] {
  border-color: var(--np-destructive);

  box-shadow: 0 0 0 3px
    color-mix(in oklch, var(--np-destructive), transparent 80%);
}

:is([data-np-button], .np-button) svg {
  width: 1rem;
  height: 1rem;

  flex-shrink: 0;
  pointer-events: none;
}

:is([data-np-button], .np-button) svg:not([class]) {
  width: 1rem;
  height: 1rem;
}

:is([data-np-button], .np-button).np-button-rounded {
  --np-button-radius: 9999px;
}

/* Variants */

.np-button,
.np-button[data-variant="default"] {
  --np-button-border: transparent;
  --np-button-hover-bg: color-mix(in oklch, var(--np-primary) 80%, transparent);
}

.np-button-outline,
.np-button[data-variant="outline"] {
  --np-button-bg: var(--np-background);
  --np-button-color: var(--np-foreground);
  --np-button-border: var(--np-border);
  --np-button-hover-bg: color-mix(in oklab, var(--np-muted) 60%, transparent);
}

.np-button-secondary,
.np-button[data-variant="secondary"] {
  --np-button-bg: var(--np-secondary);
  --np-button-color: var(--np-secondary-foreground);
  --np-button-border: var(--np-secondary);
  --np-button-hover-bg: color-mix(
    in oklch,
    var(--np-secondary),
    var(--np-foreground) 5%
  );
}

.np-button-ghost,
.np-button[data-variant="ghost"] {
  --np-button-bg: transparent;
  --np-button-color: var(--np-foreground);
  --np-button-border: transparent;
  --np-button-hover-bg: var(--np-muted);
}

.np-button-destructive,
.np-button[data-variant="destructive"] {
  --np-button-bg: color-mix(in oklch, var(--np-destructive), transparent 80%);
  --np-button-color: var(--np-destructive);
  --np-button-border: transparent;
  --np-button-hover-bg: color-mix(
    in oklch,
    var(--np-destructive),
    transparent 70%
  );
  --np-ring: color-mix(in oklch, var(--np-destructive), transparent 50%);
}

/* Link */
.np-button-link,
.np-button[data-variant="link"] {
  --np-button-bg: transparent;
  --np-button-border: transparent;
  --np-button-hover-bg: transparent;
  text-underline-offset: 4px;
  text-decoration-thickness: 0.325rem;
  --np-button-color: var(--np-primary);
  &:hover {
    --np-button-bg: transparent;
    --np-button-border: transparent;
    --np-button-hover-bg: transparent;
    --np-button-color: var(--np-primary);
    text-decoration: underline;
  }
}

/* Sizes */

.np-button-xs,
.np-button[data-size="xs"] {
  --np-button-height: 1.5rem;
  --np-button-padding-x: 0.5rem;
  --np-button-font-size: 0.75rem;
  --np-button-gap: 0.25rem;
  --np-button-radius: min(var(--np-radius-md), 10px);

  svg:not([class]) {
    width: 0.75rem;
    height: 0.75rem;
  }
}

.np-button-sm,
.np-button[data-size="sm"] {
  --np-button-height: 1.75rem;
  --np-button-padding-x: 0.625rem;
  --np-button-font-size: 0.8rem;
  --np-button-gap: 0.25rem;
  svg:not([class]) {
    width: 0.875rem;
    height: 0.875rem;
  }
}

.np-button-lg,
.np-button[data-size="lg"] {
  --np-button-height: 2.25rem;
  --np-button-padding-x: 0.625rem;
  --np-button-font-size: 0.9375rem;
  --np-button-gap: 0.375rem;
}

.np-button-icon,
.np-button[data-size="icon"],
.np-button-icon-xs,
.np-button[data-size="icon-xs"],
.np-button-icon-sm,
.np-button[data-size="icon-sm"],
.np-button-icon-lg,
.np-button[data-size="icon-lg"] {
  padding: 0;
  aspect-ratio: 1 / 1;
}

.np-button-icon-xs,
.np-button[data-size="icon-xs"] {
  --np-button-height: 1.5rem;
  --np-button-radius: min(var(--np-radius-md), 10px);

  svg:not([class]) {
    width: 0.75rem;
    height: 0.75rem;
  }
}

.np-button-icon-sm,
.np-button[data-size="icon-sm"] {
  --np-button-height: 1.75rem;
  --np-button-padding-x: 0.625rem;
}

.np-button-icon,
.np-button[data-size="icon"] {
  --np-button-height: 2rem;
}

.np-button-icon-lg,
.np-button[data-size="icon-lg"] {
  --np-button-height: 2.25rem;
}

/* Loading state */

.np-button[data-loading] > * {
  visibility: hidden;
}

.np-button[data-state="loading"],
.np-button[data-loading] {
  position: relative;
  pointer-events: none;
  opacity: 0.8;
  cursor: progress;
}

.np-button[data-state="loading"],
.np-button[data-loading]::before {
  content: "";

  width: 1em;
  height: 1em;
  flex-shrink: 0;

  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;

  animation: np-button-spin 0.6s linear infinite;
}

@keyframes np-button-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .np-button[data-state="loading"],
  .np-button[data-loading]::before {
    animation-duration: 1.2s;
  }
}
